mponents/schemas/HydroGenerationCost\"}],\"title\":\"GenericOperationCost\",\"type\":\"object\"},\"HourlyMatching\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Policy requirement that the qualified demand-side technologies have their demand met by an equal amount of generation from qualified supply in every hour, such that `sum(P)_qualified_supply >= sum(D)_qualified_demand`.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`).\",\"type\":\"boolean\"},\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"}},\"required\":[\"name\",\"id\",\"available\"],\"title\":\"HourlyMatching\",\"type\":\"object\"},\"HydroGenerationCost\":{\"description\":\"Cost representation for hydro gen units\",\"properties\":{\"cost_type\":{\"const\":\"HYDRO_GEN\",\"default\":\"HYDRO_GEN\",\"type\":\"string\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/ProductionVariableCostCurve\"}},\"required\":[\"variable_operation_cost\"],\"title\":\"HydroGenerationCost\",\"type\":\"object\"},\"InOut\":{\"description\":\"A pair of values, one for the inbound (`in`) and one for the outbound (`out`) direction of a quantity.\",\"properties\":{\"in\":{\"type\":\"number\"},\"out\":{\"type\":\"number\"}},\"title\":\"InOut\",\"type\":\"object\"},\"IncrementalCurve\":{\"description\":\"A curve whose y values are the marginal rate `f'(x)` at production level `x` — the native form for market bid stacks and incremental heat rate data. `initial_input` records the total input at the minimum production point, anchoring the absolute level and enabling conversion to an `InputOutputCurve`. Use `InputOutputCurve` when the data gives total cost at each output level.\",\"properties\":{\"curve_type\":{\"const\":\"INCREMENTAL\",\"default\":\"INCREMENTAL\",\"type\":\"string\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"#/components/schemas/LinearFunctionData\",\"PIECEWISE_STEP\":\"#/components/schemas/PiecewiseStepData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/PiecewiseStepData\"}]},\"initial_input\":{\"type\":\"number\"},\"input_at_zero\":{\"type\":\"number\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"IncrementalCurve\",\"type\":\"object\"},\"InputOutputCurve\":{\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}},\"description\":\"A curve whose y values are the total input `f(x)` at production level `x` — currency per hour against MW in a cost curve, fuel per hour against MW in a fuel curve. The y axis is an absolute quantity, not a rate; use `IncrementalCurve` for marginal-rate data.\",\"properties\":{\"curve_type\":{\"const\":\"INPUT_OUTPUT\",\"default\":\"INPUT_OUTPUT\",\"type\":\"string\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"#/components/schemas/LinearFunctionData\",\"PIECEWISE_LINEAR\":\"#/components/schemas/PiecewiseLinearData\",\"QUADRATIC\":\"#/components/schemas/QuadraticFunctionData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/QuadraticFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/PiecewiseLinearData\"}]},\"input_at_zero\":{\"type\":\"number\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"InputOutputCurve\",\"type\":\"object\"},\"LinearFunctionData\":{\"description\":\"Data for a linear function `f(x) = proportional_term * x + constant_term`.\",\"properties\":{\"constant_term\":{\"type\":\"number\"},\"function_type\":{\"const\":\"LINEAR\",\"default\":\"LINEAR\",\"type\":\"string\"},\"proportional_term\":{\"type\":\"number\"}},\"required\":[\"proportional_term\",\"constant_term\",\"function_type\"],\"title\":\"LinearFunctionData\",\"type\":\"object\"},\"MaximumCapacityRequirements\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Policy requirement that the total capacity of all eligible technologies in the target year be less than the specified limit in MW.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`).\",\"type\":\"boolean\"},\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"max_capacity_mw\":{\"description\":\"Maximum total capacity across all eligible resources. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"},\"target_year\":{\"description\":\"Year in which this requirement is applied.\",\"type\":\"integer\"}},\"required\":[\"name\",\"id\",\"available\"],\"title\":\"MaximumCapacityRequirements\",\"type\":\"object\"},\"MinMax\":{\"description\":\"A pair of values bounding a quantity from below (`min`) and from above (`max`).\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\"},\"MinMaxByKey\":{\"additionalProperties\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/MinMax\"},\"description\":\"A mapping from a stringified float key to the `MinMax` bound that applies at that key.\",\"title\":\"MinMaxByKey\",\"type\":\"object\"},\"MinimumCapacityRequirements\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Policy requirement that the total capacity of all eligible technologies in the target year be greater than or equal to the specified minimum in MW.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`).\",\"type\":\"boolean\"},\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"min_capacity_mw\":{\"description\":\"Minimum total capacity across all eligible resources. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"},\"target_year\":{\"description\":\"Year in which this requirement is applied.\",\"type\":\"integer\"}},\"required\":[\"name\",\"id\",\"available\"],\"title\":\"MinimumCapacityRequirements\",\"type\":\"object\"},\"NodalACTransportTechnology\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Nodal representation of candidate AC transmission lines between two regions. Alongside capacity limits and a capital cost curve it carries the electrical characteristics of the line — resistance, series reactance, and voltage rating — and is added in discrete units of `unit_size`.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`).\",\"type\":\"boolean\"},\"capacity_limits\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/MinMax\",\"description\":\"Allowable capacity for a transmission line. Units: MW.\",\"x-unit\":\"MW\"},\"capital_costs\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/CapitalCost\",\"description\":\"Capital and interconnection cost of adding new capacity to the nodal transmission line (capital cost in USD/MW).\"},\"end_node\":{\"description\":\"End node for transport technology.\",\"type\":\"integer\"},\"financial_data\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Struct containing relevant financial information for a technology.\",\"properties\":{\"capital_recovery_period\":{\"description\":\"Period over which capital costs are recovered for net present value calculations. Units: yr.\",\"type\":\"integer\",\"x-unit\":\"yr\"},\"debt_fraction\":{\"description\":\"Fraction of capital costs financed through debt. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"debt_rate\":{\"description\":\"Interest rate on debt financing. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"return_on_equity\":{\"description\":\"Required rate of return on equity financing. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"tax_rate\":{\"description\":\"Tax rate applied to equity returns. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"technology_base_year\":{\"description\":\"Base year for technology cost data used in NPV calculations.\",\"type\":\"integer\"}},\"required\":[\"capital_recovery_period\",\"technology_base_year\",\"debt_fraction\",\"debt_rate\",\"return_on_equity\",\"tax_rate\"],\"title\":\"TechnologyFinancialData\",\"type\":\"object\"},\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"},\"power_systems_type\":{\"description\":\"Corresponding type to be used in PCM modeling.\",\"type\":\"string\"},\"reactance\":{\"default\":0.0,\"description\":\"Series reactance for a line. Units: ohm.\",\"type\":\"number\",\"x-quantity\":\"Reactance\",\"x-unit\":\"ohm\"},\"requirements\":{\"default\":[],\"description\":\"List of requirement IDs associated with the component.\",\"items\":{\"type\":\"integer\"},\"type\":\"array\"},\"resistance\":{\"default\":0.0,\"description\":\"Technology resistance in Ohms. Units: ohm.\",\"type\":\"number\",\"x-quantity\":\"Resistance\",\"x-unit\":\"ohm\"},\"start_node\":{\"description\":\"Start node for transport technology.\",\"type\":\"integer\"},\"unit_size\":{\"default\":0.0,\"description\":\"Used for integer investment decisions. Represents the rating capacity of individual new lines. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"},\"voltage\":{\"default\":0.0,\"description\":\"Voltage rating of transmission line. Units: kV.\",\"type\":\"number\",\"x-unit\":\"kV\"}},\"required\":[\"available\",\"end_node\",\"financial_data\",\"id\",\"name\",\"power_systems_type\",\"start_node\"],\"title\":\"NodalACTransportTechnology\",\"type\":\"object\"},\"NodalHVDCTransportTechnology\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A nodal representation of candidate HVDC transmission lines between two regions, added in discrete units of `unit_size` and characterized by capacity limits, a capital cost curve, and a loss model expressed as a fraction of installed nameplate capacity.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`).\",\"type\":\"boolean\"},\"capacity_limits\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/MinMax\",\"description\":\"Allowable capacity for a transmission line. Units: MW.\",\"x-unit\":\"MW\"},\"capital_costs\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/CapitalCost\",\"description\":\"Capital and interconnection cost of adding new capacity to the nodal transmission line (capital cost in USD/MW).\"},\"end_node\":{\"description\":\"End node for transport technology.\",\"type\":\"integer\"},\"financial_data\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Struct containing relevant financial information for a technology.\",\"properties\":{\"capital_recovery_period\":{\"description\":\"Period over which capital costs are recovered for net present value calculations. Units: yr.\",\"type\":\"integer\",\"x-unit\":\"yr\"},\"debt_fraction\":{\"description\":\"Fraction of capital costs financed through debt. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"debt_rate\":{\"description\":\"Interest rate on debt financing. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"return_on_equity\":{\"description\":\"Required rate of return on equity financing. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"tax_rate\":{\"description\":\"Tax rate applied to equity returns. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"technology_base_year\":{\"description\":\"Base year for technology cost data used in NPV calculations.\",\"type\":\"integer\"}},\"required\":[\"capital_recovery_period\",\"technology_base_year\",\"debt_fraction\",\"debt_rate\",\"return_on_equity\",\"tax_rate\"],\"title\":\"TechnologyFinancialData\",\"type\":\"object\"},\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"line_loss\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/ValueCurve\",\"description\":\"Loss model coefficients. Accepts a linear model with a constant loss and a proportional loss rate, or a Piecewise loss with N segments for different proportional losses. All terms are defined as fraction of installed nameplate capacity. Units: 1.\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"},\"power_systems_type\":{\"description\":\"Corresponding type to be used in PCM modeling.\",\"type\":\"string\"},\"requirements\":{\"default\":[],\"description\":\"List of requirement IDs associated with the component.\",\"items\":{\"type\":\"integer\"},\"type\":\"array\"},\"start_node\":{\"description\":\"Start node for transport technology.\",\"type\":\"integer\"},\"unit_size\":{\"description\":\"Used for integer investment decisions. Represents the rating capacity of individual new lines. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"}},\"required\":[\"available\",\"end_node\",\"financial_data\",\"id\",\"name\",\"power_systems_type\",\"start_node\"],\"title\":\"NodalHVDCTransportTechnology\",\"type\":\"object\"},\"OutageFactors\":{\"description\":\"A pair of values representing planned and forced outage factors as fractions of total availability.\",\"properties\":{\"forced\":{\"title\":\"Forced\",\"type\":\"number\"},\"planned\":{\"title\":\"Planned\",\"type\":\"number\"}},\"title\":\"OutageFactors\",\"type\":\"object\"},\"PiecewiseLinearData\":{\"description\":\"Data for a piecewise linear function defined by (x, y) points and interpolated linearly between consecutive ones. The y values are absolute values at each x, not per-segment slopes; use `PiecewiseStepData` when the data gives per-segment rates. Points run in ascending x order, and two of them define one segment.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_LINEAR\",\"default\":\"PIECEWISE_LINEAR\",\"type\":\"string\"},\"points\":{\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-af9d0b5f8a5342306720.json#/components/schemas/XY_Coords\"},\"type\":\"array\"}},\"required\":[\"points\",\"function_type\"],\"title\":\"PiecewiseLinearData\",\"type\":\"object\"},\"PiecewiseStepData\":{\"description\":\"Data for a step function, constant on each segment, defined by the x coordinates of the segment endpoints and one y value per segment. The y values are per-segment rates, not absolute values; use `PiecewiseLinearData` when the data gives a value at each point. `x_coords` ascends and holds at least two entries, and `y_coords` holds exactly one fewer.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_STEP\",\"default\":\"PIECEWISE_STEP\",\"type\":\"string\"},\"x_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"},\"y_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"}},\"required\":[\"x_coords\",\"y_coords\",\"function_type\"],\"title\":\"PiecewiseStepData\",\"type\":\"object\"},\"PortfolioFinancialData\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Financial data for the portfolio as a whole: the base economic year that all costs are converted to a net present value in, and the discount, inflation, and interest rates used in that conversion.\",\"properties\":{\"base_year\":{\"description\":\"Base economic year. All costs will be converted to a net present value in this year.\",\"type\":\"integer\"},\"discount_rate\":{\"default\":0.0,\"description\":\"Discount rate for financial calculations. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"inflation_rate\":{\"default\":0.0,\"description\":\"Inflation rate for cost adjustments. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"},\"interest_rate\":{\"default\":0.0,\"description\":\"Interest rate for financing calculations. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Fraction\",\"x-unit\":\"1\"}},\"required\":[\"id\",\"discount_rate\",\"inflation_rate\",\"interest_rate\",\"base_year\"],\"title\":\"PortfolioFinancialData\",\"type\":\"object\"},\"PrimeMovers\":{\"description\":\"Prime mover of a generating unit — the engine, turbine, water wheel, or similar machine that drives the generator — using the code set from the EIA Form 923 instructions. `PVe` is photovoltaic, spelled that way so it does not collide with the `PV` bus type.\",\"enum\":[\"BA\",\"BT\",\"CA\",\"CC\",\"CE\",\"CP\",\"CS\",\"CT\",\"ES\",\"FC\",\"FW\",\"GT\",\"HA\",\"HB\",\"HK\",\"HY\",\"IC\",\"PS\",\"OT\",\"ST\",\"PVe